use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\ClientProgressStatements\DTOs\ClientProgressStatementData;use App\Modules\ClientProgressStatements\Services\ClientProgressStatementService;
/** @var Database $db */$db=$app->make(Database::class);/** @var ClientProgressStatementService $service */$service=$app->make(ClientProgressStatementService::class);/** @var Auth $auth */$auth=$app->make(Auth::class);
$user=$db->execute('SELECT id,name,username FROM users WHERE is_active=1 LIMIT 1')->fetch_assoc();$unit=$db->execute('SELECT id,name_ar,symbol_ar FROM units WHERE is_active=1 LIMIT 1')->fetch_assoc();if(!$user||!$unit)throw new RuntimeException('BOQ CPS fixtures unavailable.');$suffix=(string)random_int(100000,999999);$client=$project=$contract=$boq=$section=$item=$variation=0;
try{
