$first=$service->save($contract,new ClientProgressStatementData('2026-09-01',null,null,'B-1',null,[],[],[$item=>'1.2345']));$draft=$db->execute('SELECT * FROM client_progress_statement_boq_items WHERE statement_id=?',[$first])->fetch_assoc();if(!$draft||$draft['current_quantity']!=='1.2345'||(int)$draft['is_committed']!==0||$draft['description_snapshot']!==null)throw new RuntimeException('Complete BOQ draft seeding failed.');$service->approve($first);$approved=$service->find($first);if($approved['pricing_method_snapshot']!=='boq'||$approved['current_boq_amount']!=='12.35'||$approved['current_statement_amount']!=='12.35'||$approved['current_cost_amount']!==null||$approved['current_markup_amount']!==null||$approved['markup_percentage_snapshot']!==null)throw new RuntimeException('BOQ header calculation failed.');$line=$db->execute('SELECT * FROM client_progress_statement_boq_items WHERE statement_id=?',[$first])->fetch_assoc();if($line['previous_quantity']!=='0.0000'||$line['cumulative_quantity']!=='1.2345'||$line['current_amount']!=='12.35'||$line['item_code_snapshot']!==null||(int)$line['is_committed']!==1)throw new RuntimeException('BOQ snapshots failed.');
