$db->execute("INSERT INTO contract_variations(variation_code,client_contract_id,title,variation_type,variation_date,amount,amount_effect,status,approved_at,approved_by)VALUES(? ,?,'BOQ Increase','additional_work','2026-09-02','5.00','increase','approved',NOW(),?)",['BCPV-'.$suffix,$contract,(int)$user['id']]);$variation=(int)$db->connection()->insert_id;$positive=$service->save($contract,new ClientProgressStatementData('2026-09-03',null,null,'B-5',null,[],[['variation_id'=>$variation,'current_billed_amount'=>'5.00']],[$item=>'0.0000']));$service->approve($positive);if($service->find($positive)['current_statement_amount']!=='5.00')throw new RuntimeException('Pure positive Variation BOQ statement failed.');
}finally{$auth->logout();if($contract){$db->execute('DELETE d FROM client_progress_statement_boq_items d JOIN client_progress_statements s ON s.id=d.statement_id WHERE s.client_contract_id=?',[$contract]);$db->execute('DELETE d FROM client_progress_statement_variations d JOIN client_progress_statements s ON s.id=d.statement_id WHERE s.client_contract_id=?',[$contract]);$db->execute('DELETE FROM client_progress_statements WHERE client_contract_id=?',[$contract]);}$variation&&$db->execute('DELETE FROM contract_variations WHERE id=?',[$variation]);$item&&$db->execute('DELETE FROM contract_boq_items WHERE id=?',[$item]);$section&&$db->execute('DELETE FROM contract_boq_sections WHERE id=?',[$section]);$boq&&$db->execute('DELETE FROM contract_boqs WHERE id=?',[$boq]);$contract&&$db->execute('DELETE FROM client_contracts WHERE id=?',[$contract]);$project&&$db->execute('DELETE FROM projects WHERE id=?',[$project]);$client&&$db->execute('DELETE FROM clients WHERE id=?',[$client]);}
